export function routeContentDate(path: string): RouteContentDate | null {
  return ROUTE_CONTENT_DATES[path] ?? null;
}

export function lastModifiedFor(path: string): Date {
  const row = ROUTE_CONTENT_DATES[path];
  if (!row) {
    throw new Error(`Missing content date for ${path}`);
  }
  return new Date(`${row.modified}T00:00:00.000Z`);
}
